def backtest(modelo, X, y, n_splits=6, horizonte=28, gap=0):
    filas = []
    for k, (i_tr, i_te) in enumerate(TimeSeriesSplit(n_splits, test_size=horizonte, gap=gap).split(X)):
        modelo.fit(X.iloc[i_tr], y.iloc[i_tr])
        filas.append({"ronda": k,
                      "desde": X.index[i_te[0]], "hasta": X.index[i_te[-1]],
                      "mae": mean_absolute_error(y.iloc[i_te], modelo.predict(X.iloc[i_te])),
                      "mae_ingenuo": mean_absolute_error(y.iloc[i_te], X["lag_7"].iloc[i_te])})
    return pd.DataFrame(filas)

