import numpy as np

def cobertura_y_ancho(y, bajo, alto):
    dentro = (y >= bajo) & (y <= alto)
    return float(dentro.mean()), float(np.mean(alto - bajo))

def mase(y_real, y_pred, y_entreno, m=7):
    escala = np.mean(np.abs(y_entreno[m:] - y_entreno[:-m]))
    return np.mean(np.abs(y_real - y_pred)) / escala

