import joblib
import pandas as pd
from fastapi import FastAPI
from pydantic import BaseModel, Field

VERSION = "1.3.0"
modelo = joblib.load(f"modelos/churn-{VERSION}.joblib")
UMBRAL = 0.18
app = FastAPI(title="Riesgo de abandono")


class Cliente(BaseModel):
    meses_cliente: int = Field(ge=0, le=600)
    dias_uso_30: int = Field(ge=0, le=31)
    dias_uso_90: int = Field(ge=0, le=92)
    dias_sin_uso: int | None = Field(default=None, ge=0)
    tickets_30: int = Field(ge=0)
    plan: str
    pais: str


@app.get("/salud")
def salud():
    return {"estado": "ok", "version": VERSION}


@app.post("/predecir")
def predecir(c: Cliente):
    prob = float(modelo.predict_proba(pd.DataFrame([c.model_dump()]))[0, 1])
    return {"probabilidad": round(prob, 4), "alerta": prob >= UMBRAL, "version": VERSION}

