UMBRALES = {"psi_puntaje": 0.25, "caida_lift": 0.20, "nulos_max": 0.05}

def revisar_salud(psi_puntaje, lift_actual, lift_referencia, pct_nulos):
    alertas = []
    if pct_nulos > UMBRALES["nulos_max"]:
        alertas.append("calidad: demasiados nulos; detener el scoring")
    if psi_puntaje > UMBRALES["psi_puntaje"]:
        alertas.append(f"deriva: PSI del puntaje {psi_puntaje:.2f}")
    if lift_actual < lift_referencia * (1 - UMBRALES["caida_lift"]):
        alertas.append(f"rendimiento: lift {lift_actual:.1f} vs {lift_referencia:.1f}")
    return alertas or ["ok"]

