import numpy as np

def precision_en_top(y_true, prob, k=500):
    orden = np.argsort(prob)[::-1][:k]
    return float(np.asarray(y_true)[orden].mean())

def lift_en_top(y_true, prob, k=500):
    return precision_en_top(y_true, prob, k) / float(np.mean(y_true))

